text:
As cadeias e nichos do painel cobrem as atividades mais importantes do estado, mas não todas. Esta página mede todas as subclasses da CNAE com emprego formal em Pernambuco, para responder duas perguntas: em que um município ou região é especializado, e onde está uma atividade qualquer. A medida é o quociente locacional (QL) do emprego formal: o peso da atividade no território dividido pelo peso dela no estado. Acima de 1, o território é especializado.



Retrato das vocações de Pernambuco: cada município pela cadeia ou nicho em que é mais especializado.



Baixe o retrato em PNG ou PDF.



Código
V = FileAttachment("dados/vocacoes.json").json()
geo = FileAttachment("dados/malha_pe.geojson").json()
PROD = FileAttachment("dados/producao.json").json()
tabProd = (linhas, n = 15, total = null) =&gt; {
  if (!linhas || !linhas.length) return html`&lt;p&gt;Sem produção agropecuária registrada pelo IBGE.&lt;/p&gt;`;
  const PR = PROD.produtos;
  const t = linhas.map(([p, v, q, ql]) =&gt; ({p, nome: PR.nome[p], grupo: PR.grupo[p], v, q, ql, un: PR.unidade[p], part: PR.valor[p] ? v / PR.valor[p] : null}))
    .filter(d =&gt; d.v &gt; 0).sort((a, b) =&gt; b.v - a.v);
  const tot = d3.sum(t, d =&gt; d.v);
  return html`&lt;p&gt;Valor da produção agropecuária e da aquicultura: &lt;b&gt;${reaisMil(tot)}&lt;/b&gt;${total ? html`, ${(100 * tot / total).toLocaleString("pt-BR", {maximumFractionDigits: 1})}% do estado` : ""} (IBGE ${PROD.anos[PROD.anos.length - 1]}).&lt;/p&gt;
  &lt;table class="rx-tab"&gt;&lt;thead&gt;&lt;tr&gt;&lt;th&gt;Produto&lt;/th&gt;&lt;th&gt;Valor&lt;/th&gt;&lt;th&gt;Quantidade&lt;/th&gt;&lt;th&gt;QL do valor&lt;/th&gt;&lt;th&gt;% de PE&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;&lt;tbody&gt;
  ${t.slice(0, n).map(d =&gt; html`&lt;tr class="${d.ql &gt;= 1 ? "rx-esp" : ""}"&gt;&lt;td&gt;${d.nome} &lt;span class="voc-cod"&gt;${d.grupo}&lt;/span&gt;&lt;/td&gt;&lt;td&gt;${reaisMil(d.v)}&lt;/td&gt;
    &lt;td&gt;${d.q ? d.q.toLocaleString("pt-BR") + " " + (d.un ?? "").toLowerCase() : "–"}&lt;/td&gt;&lt;td&gt;${d.ql == null ? "–" : d.ql.toLocaleString("pt-BR", {maximumFractionDigits: 1, minimumFractionDigits: 1})}&lt;/td&gt;
    &lt;td&gt;${d.part == null ? "–" : (100 * d.part).toLocaleString("pt-BR", {maximumFractionDigits: 1}) + "%"}&lt;/td&gt;&lt;/tr&gt;`)}&lt;/tbody&gt;&lt;/table&gt;`;
}
reaisMil = v =&gt; v == null ? "–" : v &gt;= 1e6 ? "R$ " + (v / 1e6).toLocaleString("pt-BR", {maximumFractionDigits: 2}) + " bi" : v &gt;= 1e3 ? "R$ " + (v / 1e3).toLocaleString("pt-BR", {maximumFractionDigits: 1}) + " mi" : "R$ " + v.toLocaleString("pt-BR") + " mil"
nf = (x, d = 0) =&gt; x == null || isNaN(x) ? "–" : x.toLocaleString("pt-BR", {maximumFractionDigits: d, minimumFractionDigits: d})
A = V.atividades
nomeMun = new Map(geo.features.map(f =&gt; [f.properties.id_municipio, f.properties.name_muni]))
rdMun = new Map(geo.features.map(f =&gt; [f.properties.id_municipio, f.properties.rd]))
listaMun = [...Object.keys(V.municipios)].map(id =&gt; ({id, nome: nomeMun.get(id) ?? id, tipo: "Município"})).sort((a, b) =&gt; a.nome.localeCompare(b.nome, "pt-BR"))
listaRd = Object.keys(V.regioes).sort().map(r =&gt; ({id: r, nome: r, tipo: "Região de Desenvolvimento"}))
tagCad = i =&gt; (A.cadeias[i] || "").split(";").filter(Boolean).map(c =&gt; html`&lt;a class="voc-cad" href="cadeias/${c}.html"&gt;${V.cadeias[c] ?? c}&lt;/a&gt;`)























































































Em que o território é especializadoOnde a atividade estáOnde o produto agropecuário está




Código
viewof terr = Inputs.select([...listaRd, ...listaMun], {label: "Município ou RD", format: d =&gt; d.tipo === "Município" ? d.nome : "RD " + d.nome,
  value: listaMun.find(d =&gt; d.nome === "Caruaru")})
viewof soEsp = Inputs.toggle({label: "Só atividades com QL ≥ 1", value: true})
viewof ordem = Inputs.radio(["Empregos", "QL"], {label: "Ordenar por", value: "Empregos"})

























