  const linhas = (terr.tipo === "Município" ? V.municipios : V.regioes)[terr.id] ?? [];
  const tot = d3.sum(linhas, l =&gt; l[1]);
  const t = linhas.map(([i, e, s, q]) =&gt; ({i, atividade: A.nome[i], cod: A.cod[i], emprego: e, estab: s, ql: q, part: e / A.emprego[i]}))
    .filter(d =&gt; d.emprego &gt;= V.emprego_minimo && (!soEsp || d.ql &gt;= 1)).sort((a, b) =&gt; ordem === "QL" ? b.ql - a.ql : b.emprego - a.emprego);
