  &lt;div class="voc-tab"&gt;&lt;table class="table table-sm"&gt;&lt;thead&gt;&lt;tr&gt;&lt;th&gt;Atividade (subclasse CNAE)&lt;/th&gt;&lt;th&gt;Empregos&lt;/th&gt;&lt;th&gt;Estab.&lt;/th&gt;&lt;th&gt;QL&lt;/th&gt;&lt;th&gt;% de PE&lt;/th&gt;&lt;th&gt;Cadeia ou nicho&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;&lt;tbody&gt;
  ${t.slice(0, 150).map(d =&gt; html`&lt;tr&gt;&lt;td&gt;${d.atividade} &lt;span class="voc-cod"&gt;${d.cod}&lt;/span&gt;&lt;/td&gt;&lt;td&gt;${nf(d.emprego)}&lt;/td&gt;&lt;td&gt;${nf(d.estab)}&lt;/td&gt;
    &lt;td&gt;&lt;b&gt;${nf(d.ql, 1)}&lt;/b&gt;&lt;/td&gt;&lt;td&gt;${nf(100 * d.part, 1)}%&lt;/td&gt;&lt;td&gt;${tagCad(d.i)}&lt;/td&gt;&lt;/tr&gt;`)}&lt;/tbody&gt;&lt;/table&gt;&lt;/div&gt;
  ${t.length &gt; 150 ? html`&lt;p class="fonte"&gt;Mostrando as 150 primeiras de ${nf(t.length)}.&lt;/p&gt;` : ""}`;
}









Código
html`&lt;h4&gt;Produção agropecuária&lt;/h4&gt;${tabProd(((terr.tipo === "Município" ? PROD.municipios : PROD.regioes) ?? {})[terr.id], 20, d3.sum(PROD.produtos.valor))}`








Fonte: IBGE, Produção Agrícola Municipal, Pesquisa da Pecuária Municipal e produção da aquicultura, via SIDRA. QL do valor: peso do produto no valor agropecuário do território dividido pelo peso no estado; só com R$ 50 mil ou mais. Rebanhos aparecem em cabeças, sem valor nem QL.





Código
opcoes = A.nome.map((n, i) =&gt; ({i, nome: n, cod: A.cod[i], emprego: A.emprego[i], n_mun: A.n_mun[i], secao: A.nome_secao[i]}))
viewof busca = Inputs.search(opcoes, {placeholder: "Busque uma atividade: café, uva, cerâmica, software, hotel...", columns: ["nome", "cod", "secao"]})
viewof escolha = Inputs.table(busca, {columns: ["nome", "cod", "emprego", "n_mun"], header: {nome: "Atividade", cod: "Subclasse", emprego: "Empregos em PE", n_mun: "Municípios"},
  format: {emprego: d =&gt; nf(d)}, multiple: false, required: false, rows: 8, value: opcoes.find(d =&gt; /cultivo de café/i.test(d.nome)) ?? opcoes[0]})

























Código
{
  const sel = escolha ?? opcoes[0];
  const por = new Map();
  for (const [id, linhas] of Object.entries(V.municipios)) for (const l of linhas) if (l[0] === sel.i) por.set(id, {emprego: l[1], estab: l[2], ql: l[3]});
  const feats = geo.features.map(f =&gt; ({...f, properties: {...f.properties, ...(por.get(f.properties.id_municipio) ?? {})}}));
  const faixa = q =&gt; q == null ? "Sem emprego formal" : q &lt; 1 ? "Abaixo de 1" : q &lt; 2 ? "1 a 2" : q &lt; 5 ? "2 a 5" : "5 ou mais";
  const dom = ["Sem emprego formal", "Abaixo de 1", "1 a 2", "2 a 5", "5 ou mais"];
  const mapa = Plot.plot({
    projection: {type: "mercator", domain: {type: "FeatureCollection", features: feats}}, width: 1000, height: 340,
    color: {domain: dom, range: ["#EEF1F4", "#C9DCEC", "#7FB1D8", "#2E78B7", "#023471"], legend: true},
    marks: [Plot.geo(feats, {fill: d =&gt; faixa(d.properties.emprego &gt;= V.emprego_minimo ? d.properties.ql : (d.properties.emprego ? 0.5 : null)),
      stroke: "white", strokeWidth: 0.4,
      title: d =&gt; `${d.properties.name_muni}\n${d.properties.emprego ? nf(d.properties.emprego) + " empregos · QL " + nf(d.properties.ql, 1) : "sem emprego formal"}`})]});
  const t = [...por.entries()].map(([id, d]) =&gt; ({mun: nomeMun.get(id) ?? id, rd: rdMun.get(id), ...d})).sort((a, b) =&gt; b.emprego - a.emprego);
  return html`&lt;h4&gt;${sel.nome} &lt;span class="voc-cod"&gt;${sel.cod}&lt;/span&gt;&lt;/h4&gt;
    &lt;p&gt;${nf(A.emprego[sel.i])} empregos formais e ${nf(A.estab[sel.i])} estabelecimentos em ${nf(A.n_mun[sel.i])} municípios (RAIS ${V.ano}). ${tagCad(sel.i).length ? html`Faz parte de: ${tagCad(sel.i)}` : ""}&lt;/p&gt;
    ${mapa}
    &lt;div class="voc-tab"&gt;&lt;table class="table table-sm"&gt;&lt;thead&gt;&lt;tr&gt;&lt;th&gt;Município&lt;/th&gt;&lt;th&gt;RD&lt;/th&gt;&lt;th&gt;Empregos&lt;/th&gt;&lt;th&gt;Estab.&lt;/th&gt;&lt;th&gt;QL&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;&lt;tbody&gt;
    ${t.slice(0, 40).map(d =&gt; html`&lt;tr&gt;&lt;td&gt;${d.mun}&lt;/td&gt;&lt;td class="voc-cod"&gt;${d.rd ?? ""}&lt;/td&gt;&lt;td&gt;${nf(d.emprego)}&lt;/td&gt;&lt;td&gt;${nf(d.estab)}&lt;/td&gt;&lt;td&gt;${d.emprego &gt;= V.emprego_minimo ? nf(d.ql, 1) : "–"}&lt;/td&gt;&lt;/tr&gt;`)}&lt;/tbody&gt;&lt;/table&gt;&lt;/div&gt;
    &lt;p class="fonte"&gt;Municípios com menos de ${V.emprego_minimo} empregos na atividade aparecem como "abaixo de 1" no mapa e sem QL na tabela, para evitar QL alto com poucos vínculos.&lt;/p&gt;`;
}











