{
  const sel = escP ?? prodOp[0];
  const por = new Map();
  for (const [id, ls] of Object.entries(PROD.municipios)) for (const l of ls) if (l[0] === sel.i) por.set(id, {valor: l[1], qtd: l[2], ql: l[3]});
  const feats = geo.features.map(f =&gt; ({...f, properties: {...f.properties, ...(por.get(f.properties.id_municipio) ?? {})}}));
  const rebanho = /Rebanhos/.test(sel.grupo);
  const faixa = d =&gt; rebanho ? (d.qtd ? "Com rebanho" : "Sem registro") : d.ql == null ? (d.valor ? "Abaixo de R$ 50 mil" : "Sem registro") : d.ql &lt; 1 ? "QL abaixo de 1" : d.ql &lt; 2 ? "QL 1 a 2" : d.ql &lt; 5 ? "QL 2 a 5" : "QL 5 ou mais";
  const dom = rebanho ? ["Sem registro", "Com rebanho"] : ["Sem registro", "Abaixo de R$ 50 mil", "QL abaixo de 1", "QL 1 a 2", "QL 2 a 5", "QL 5 ou mais"];
  const cores = rebanho ? ["#EEF1F4", "#2E9E5B"] : ["#EEF1F4", "#E3EDE5", "#C3DFC9", "#7CC08E", "#2E9E5B", "#145A32"];
  const t = [...por.entries()].map(([id, d]) =&gt; ({mun: nomeMun.get(id) ?? id, rd: rdMun.get(id), ...d})).sort((a, b) =&gt; (b.valor || b.qtd) - (a.valor || a.qtd));
  const un = (PROD.produtos.unidade[sel.i] ?? "").toLowerCase();
  return html`&lt;h4&gt;${sel.nome} &lt;span class="voc-cod"&gt;${sel.grupo}&lt;/span&gt;&lt;/h4&gt;
    &lt;p&gt;${sel.valor ? html`${reaisMil(sel.valor)} de valor da produção em ` : ""}${nf(sel.n_mun)} municípios (IBGE ${PROD.produtos.ano[sel.i] ?? ""}).&lt;/p&gt;
    ${Plot.plot({projection: {type: "mercator", domain: {type: "FeatureCollection", features: feats}}, width: 1000, height: 340,
      color: {domain: dom, range: cores, legend: true},
      marks: [Plot.geo(feats, {fill: d =&gt; faixa(d.properties), stroke: "white", strokeWidth: 0.4,
        title: d =&gt; `${d.properties.name_muni}\n${d.properties.valor ? reaisMil(d.properties.valor) : ""} ${d.properties.qtd ? nf(d.properties.qtd) + " " + un : "sem registro"}${d.properties.ql != null ? " · QL " + nf(d.properties.ql, 1) : ""}`})]})}
    &lt;div class="voc-tab"&gt;&lt;table class="table table-sm"&gt;&lt;thead&gt;&lt;tr&gt;&lt;th&gt;Município&lt;/th&gt;&lt;th&gt;RD&lt;/th&gt;&lt;th&gt;Valor&lt;/th&gt;&lt;th&gt;Quantidade&lt;/th&gt;&lt;th&gt;QL do valor&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;&lt;tbody&gt;
    ${t.slice(0, 40).map(d =&gt; html`&lt;tr&gt;&lt;td&gt;${d.mun}&lt;/td&gt;&lt;td class="voc-cod"&gt;${d.rd ?? ""}&lt;/td&gt;&lt;td&gt;${d.valor ? reaisMil(d.valor) : "–"}&lt;/td&gt;&lt;td&gt;${d.qtd ? nf(d.qtd) + " " + un : "–"}&lt;/td&gt;&lt;td&gt;${d.ql == null ? "–" : nf(d.ql, 1)}&lt;/td&gt;&lt;/tr&gt;`)}&lt;/tbody&gt;&lt;/table&gt;&lt;/div&gt;`;
}








Fonte: IBGE, Produção Agrícola Municipal, Pesquisa da Pecuária Municipal e produção da aquicultura, via SIDRA. QL do valor: peso do produto no valor agropecuário do território dividido pelo peso no estado; só com R$ 50 mil ou mais. Rebanhos aparecem em cabeças, sem valor nem QL.





Fonte: RAIS (MTE), vínculos ativos em 31/12, via Base dos Dados; diretório CNAE 2.0 (IBGE). Elaboração própria. A RAIS só cobre o emprego formal: atividades com muita informalidade ou trabalho por conta própria (como parte da agricultura familiar e da confecção) aparecem menores do que são. Para essas, veja nas páginas das cadeias o QL das empresas (com MEI) e da produção do IBGE.

Código
regs = FileAttachment("dados/regioes.json").json()
geo0 = FileAttachment("dados/malha_pe.geojson").json()
geo = ({type: "FeatureCollection", features: geo0.features.map(f =&gt; {
  if (d3.geoArea(f) &lt;= 2 * Math.PI) return f;
  const g = f.geometry;
  const rev = poly =&gt; poly.map(r =&gt; r.slice().reverse());
  const coords = g.type === "Polygon" ? rev(g.coordinates) : g.coordinates.map(rev);
  return {...f, geometry: {...g, coordinates: coords}};
})})
import {cartoes, blocoEmpresas, blocoQualif, blocoEducacao, blocoIcms, blocoAgro, blocoInfra, listaCursos, blocoAssociativas} from "./territorio.js"
PROD = FileAttachment("dados/producao.json").json()
tabProd = (linhas, n = 15, total = null) =&gt; {
  if (!linhas || !linhas.length) return html`&lt;p&gt;Sem produção agropecuária registrada pelo IBGE.&lt;/p&gt;`;
  const PR = PROD.produtos;
  const t = linhas.map(([p, v, q, ql]) =&gt; ({p, nome: PR.nome[p], grupo: PR.grupo[p], v, q, ql, un: PR.unidade[p], part: PR.valor[p] ? v / PR.valor[p] : null}))
    .filter(d =&gt; d.v &gt; 0).sort((a, b) =&gt; b.v - a.v);
  const tot = d3.sum(t, d =&gt; d.v);
  return html`&lt;p&gt;Valor da produção agropecuária e da aquicultura: &lt;b&gt;${reaisMil(tot)}&lt;/b&gt;${total ? html`, ${(100 * tot / total).toLocaleString("pt-BR", {maximumFractionDigits: 1})}% do estado` : ""} (IBGE ${PROD.anos[PROD.anos.length - 1]}).&lt;/p&gt;
  &lt;table class="rx-tab"&gt;&lt;thead&gt;&lt;tr&gt;&lt;th&gt;Produto&lt;/th&gt;&lt;th&gt;Valor&lt;/th&gt;&lt;th&gt;Quantidade&lt;/th&gt;&lt;th&gt;QL do valor&lt;/th&gt;&lt;th&gt;% de PE&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;&lt;tbody&gt;
  ${t.slice(0, n).map(d =&gt; html`&lt;tr class="${d.ql &gt;= 1 ? "rx-esp" : ""}"&gt;&lt;td&gt;${d.nome} &lt;span class="voc-cod"&gt;${d.grupo}&lt;/span&gt;&lt;/td&gt;&lt;td&gt;${reaisMil(d.v)}&lt;/td&gt;
    &lt;td&gt;${d.q ? d.q.toLocaleString("pt-BR") + " " + (d.un ?? "").toLowerCase() : "–"}&lt;/td&gt;&lt;td&gt;${d.ql == null ? "–" : d.ql.toLocaleString("pt-BR", {maximumFractionDigits: 1, minimumFractionDigits: 1})}&lt;/td&gt;
    &lt;td&gt;${d.part == null ? "–" : (100 * d.part).toLocaleString("pt-BR", {maximumFractionDigits: 1}) + "%"}&lt;/td&gt;&lt;/tr&gt;`)}&lt;/tbody&gt;&lt;/table&gt;`;
}
reaisMil = v =&gt; v == null ? "–" : v &gt;= 1e6 ? "R$ " + (v / 1e6).toLocaleString("pt-BR", {maximumFractionDigits: 2}) + " bi" : v &gt;= 1e3 ? "R$ " + (v / 1e3).toLocaleString("pt-BR", {maximumFractionDigits: 1}) + " mi" : "R$ " + v.toLocaleString("pt-BR") + " mil"
nomesR = regs.map(r =&gt; r.rd).sort((a, b) =&gt; a.localeCompare(b, "pt-BR"))
inicialR = {
  const q = new URLSearchParams(window.location.search).get("r");
  return q && nomesR.includes(q) ? q : "Metropolitana";
}
viewof rsel = Inputs.select(nomesR, {label: "Região de Desenvolvimento", value: inicialR})
r = {
  try { history.replaceState(null, "", "?r=" + encodeURIComponent(rsel)); } catch (e) {}
  return regs.find(x =&gt; x.rd === rsel);
}
ids = new Set(r.municipios.map(d =&gt; d.id))
nf = (x, d = 0) =&gt; x == null || isNaN(x) ? "–" : x.toLocaleString("pt-BR", {maximumFractionDigits: d, minimumFractionDigits: d})
pct = (x, d = 1) =&gt; x == null || isNaN(x) ? "–" : (100 * x).toLocaleString("pt-BR", {maximumFractionDigits: d, minimumFractionDigits: d}) + "%"
reais = x =&gt; x == null ? "–" : x &gt;= 1e9 ? "R$ " + nf(x / 1e9, 2) + " bi" : x &gt;= 1e6 ? "R$ " + nf(x / 1e6, 1) + " mi" : "R$ " + nf(x / 1e3, 0) + " mil"
AZUL = "#1F4E79"; LAR = "#E07A1F"
