      ${d.pct_mei != null && d.empresas ? html`&lt;span&gt;${nf(d.empresas)} empresas, ${nf(100 * d.pct_mei, 0)}% MEI&lt;/span&gt;` : ""}&lt;/div&gt;` : ""}
    ${x.producao.length ? html`&lt;div class="rx-cc-bloco"&gt;&lt;h5&gt;Produção (IBGE)&lt;/h5&gt;&lt;table class="rx-tab"&gt;&lt;tbody&gt;
