    ${listaMaiores((t.maiores ?? {})[d.cadeia_id], {html})}
    ${x.destinos.length ? html`&lt;div class="rx-cc-bloco"&gt;&lt;h5&gt;Principais destinos&lt;/h5&gt;&lt;p&gt;${x.destinos.map(p =&gt; `${p.pais} (${usd(p.v)})`).join(" · ")}&lt;/p&gt;&lt;/div&gt;` : ""}
